const SubscriberPayloadDtoSchema = z
  .object({
    firstName: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'First name of the subscriber', example: 'John' }),
    lastName: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Last name of the subscriber', example: 'Doe' }),
    email: z
      .email()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Email address of the subscriber', example: 'john.doe@example.com' }),
    phone: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Phone number of the subscriber', example: '+1234567890' }),
    avatar: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Avatar URL or identifier',
        example: 'https://example.com/avatar.jpg',
      }),
    locale: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Locale of the subscriber', example: 'en-US' }),
    timezone: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Timezone of the subscriber', example: 'America/New_York' }),
    data: z
      .looseObject({})
      .nullable()
      .exactOptional()
      .openapi({ description: 'Additional custom data associated with the subscriber' }),
    subscriberId: z
      .string()
      .min(1)
      .openapi({
        description:
          'The internal identifier you used to create this subscriber, usually correlates to the id the user in your systems',
      }),
    channels: z
      .array(SubscriberChannelDtoSchema)
      .exactOptional()
      .openapi({ description: 'An optional array of subscriber channels.' }),
  })
  .openapi({ required: ['subscriberId'] })
  .openapi('SubscriberPayloadDto')

const TriggerRecipientsTypeEnumSchema = z
  .enum(['Subscriber', 'Topic'])
  .openapi('TriggerRecipientsTypeEnum')

const TopicPayloadDtoSchema = z
  .object({
    topicKey: z.string().min(1),
    type: TriggerRecipientsTypeEnumSchema,
    exclude: z
      .array(z.string())
      .max(100)
      .exactOptional()
      .openapi({
        description: 'Optional array of subscriber IDs to exclude from the topic trigger',
      }),
  })
  .openapi({ required: ['topicKey', 'type'] })
  .openapi('TopicPayloadDto')

const TenantPayloadDtoSchema = z
  .object({
    identifier: z.string().exactOptional(),
    name: z.string().exactOptional(),
    data: z.looseObject({}).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('TenantPayloadDto')

const TriggerEventRequestDtoSchema = z
  .object({
    name: z
      .string()
      .openapi({
        description:
          'The trigger identifier of the workflow you wish to send. This identifier can be found on the workflow page.',
        example: 'workflow_identifier',
        'x-speakeasy-name-override': 'workflowId',
      }),
    payload: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          'The payload object is used to pass additional custom information that could be \n    used to render the workflow, or perform routing rules based on it. \n      This data will also be available when fetching the notifications feed from the API to display certain parts of the UI.',
        example: { comment_id: 'string', post: { text: 'string' } },
      }),
    bridgeUrl: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Optional Bridge Endpoint URL used to route this trigger to a specific Bridge application. Useful during local development when multiple engineers share an organization: set this to your personal tunnel URL from `npx novu@latest dev` (for example via NOVU_BRIDGE_URL) so app-fired triggers hit your machine instead of the environment's synced Bridge URL. Must be a publicly reachable https URL — private or localhost addresses are rejected.",
        example: 'https://your-tunnel.novu.co/api/novu',
      }),
    overrides: TriggerOverridesSchema.exactOptional().openapi({
      description: 'This could be used to override provider specific configurations',
      example: { fcm: { data: { key: 'value' } } },
    }),
    agentId: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Override the workflow-assigned agent for this trigger using the public agent identifier. Omit to use the workflow default; pass null to disable agent routing for this execution.',
        example: 'support-agent',
      }),
    to: z
      .xor([
        z.array(
          z.xor([
            SubscriberPayloadDtoSchema,
            TopicPayloadDtoSchema,
            z
              .string()
              .min(1)
              .openapi({
                description: 'Unique identifier of a subscriber in your systems',
                example: 'SUBSCRIBER_ID',
              }),
          ]),
        ),
        z
          .string()
          .min(1)
          .openapi({
            description: 'Unique identifier of a subscriber in your systems',
            example: 'SUBSCRIBER_ID',
          }),
        SubscriberPayloadDtoSchema,
        TopicPayloadDtoSchema,
      ])
      .openapi({
        description:
          'The recipients list of people who will receive the notification. Maximum number of recipients can be 100.',
      }),
    transactionId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A unique identifier for deduplication. If the same **transactionId** is sent again, \n      the trigger is ignored. Useful to prevent duplicate notifications. The retention period depends on your billing tier.',
      }),
    actor: z
      .xor([
        z.string().openapi({ description: 'Unique identifier of a subscriber in your systems' }),
        SubscriberPayloadDtoSchema,
      ])
      .exactOptional()
      .openapi({
        description:
          "It is used to display the Avatar of the provided actor's subscriber id or actor object.\n    If a new actor object is provided, we will create a new subscriber in our system",
      }),
    tenant: z
      .xor([
        z.string().openapi({ description: 'Unique identifier of a tenant in your system' }),
        TenantPayloadDtoSchema,
      ])
      .exactOptional()
      .openapi({
        description:
          'It is used to specify a tenant context during trigger event.\n    Existing tenants will be updated with the provided details.',
      }),
    context: z
      .record(
        z.string(),
        z.xor([
          z.string().openapi({ description: 'Simple context id', example: 'org-acme' }),
          z
            .object({
              id: z.string().openapi({ example: 'org-acme' }),
              data: z
                .looseObject({})
                .exactOptional()
                .openapi({
                  description: 'Optional additional context data',
                  example: { name: 'Acme Corp', region: 'us-east-1' },
                }),
            })
            .openapi({
              description: 'Rich context object with id and optional data',
              required: ['id'],
            }),
        ]),
      )
      .exactOptional(),
  })
  .openapi({ required: ['name', 'to'] })
  .openapi('TriggerEventRequestDto')

type BulkTriggerEventDtoType = { events: z.infer<typeof TriggerEventRequestDtoSchema>[] }

const BuilderFieldTypeEnumSchema = z
  .enum(['BOOLEAN', 'TEXT', 'DATE', 'NUMBER', 'STATEMENT', 'LIST', 'MULTI_LIST', 'GROUP'])
  .openapi('BuilderFieldTypeEnum')

const FieldFilterPartDtoSchema = z
  .object({
    field: z.string(),
    value: z.string(),
    operator: z.enum([
      'LARGER',
      'SMALLER',
      'LARGER_EQUAL',
      'SMALLER_EQUAL',
      'EQUAL',
      'NOT_EQUAL',
      'ALL_IN',
      'ANY_IN',
      'NOT_IN',
      'BETWEEN',
      'NOT_BETWEEN',
      'LIKE',
      'NOT_LIKE',
      'IN',
    ]),
    on: z.enum(['subscriber', 'payload']),
  })
  .openapi({ required: ['field', 'value', 'operator', 'on'] })
  .openapi('FieldFilterPartDto')

const StepFilterDtoSchema = z
  .object({
    isNegated: z.boolean(),
    type: BuilderFieldTypeEnumSchema,
    value: z.enum(['AND', 'OR']),
    children: z.array(FieldFilterPartDtoSchema),
  })
  .openapi({ required: ['isNegated', 'type', 'value', 'children'] })
  .openapi('StepFilterDto')

const MessageTemplateDtoSchema = z.looseObject({}).openapi('MessageTemplateDto')

type ActivityNotificationStepResponseDtoType = {
  _id: string
  active: boolean
  replyCallback?: { [key: string]: unknown }
  controlVariables?: { [key: string]: unknown }
  metadata?: { [key: string]: unknown }
  issues?: { [key: string]: unknown }
  filters: z.infer<typeof StepFilterDtoSchema>[]
  template?: z.infer<typeof MessageTemplateDtoSchema>
  variants?: ActivityNotificationStepResponseDtoType[]
  _templateId: string
  name?: string
  _parentId?: string | null
}

