const CreateEnvironmentVariableRequestDtoSchema = z
  .object({
    key: z
      .string()
      .regex(/^[A-Za-z][A-Za-z0-9_]*$/)
      .max(256)
      .openapi({
        description:
          'Unique key for the variable. Must start with a letter and contain only letters, digits, and underscores.',
      }),
    type: z.literal('string').exactOptional().openapi({ description: 'The type of the variable' }),
    isSecret: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Whether this variable is a secret (encrypted at rest, masked in responses)',
      }),
    values: z
      .array(EnvironmentVariableValueDtoSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional(),
  })
  .openapi({ required: ['key'] })
  .openapi('CreateEnvironmentVariableRequestDto')

