export const postV2TranslationsUploadRoute = createRoute({
  method: 'post',
  path: '/v2/translations/upload',
  tags: ['Translations'],
  summary: 'Upload translation files',
  description:
    'Upload one or more JSON translation files for a specific workflow. Files name must match the locale, e.g. en_US.json. Supports both "files" and "files[]" field names for backwards compatibility.',
  operationId: 'TranslationController_uploadTranslationFiles',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              resourceId: z
                .string()
                .openapi({
                  description:
                    'The resource ID to associate localizations with. Accepts identifier or slug format',
                  example: 'welcome-email',
                }),
              resourceType: z
                .enum(['workflow', 'layout'])
                .openapi({ description: 'The resource type to associate localizations with' }),
              files: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.file().openapi({ type: 'string', format: 'binary' })),
                )
                .openapi({
                  description:
                    'One or more JSON translation files. Filenames must match locale format (e.g., en_US.json, fr_FR.json). Field name can be "files" or "files[]".',
                }),
            })
            .openapi({ required: ['resourceId', 'resourceType', 'files'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Upload results',
      content: { 'application/json': { schema: UploadTranslationsResponseDtoSchema } },
    },
  },
  security: [{ secretKey: [] }, { secretKey: [] }],
})

